def sequence(value, maximum):
    if type(value) is not list or len(value) > maximum:
        raise ValueError('array')
    return value


def text(value, maximum=TEMPLATE_LIMIT):
    if type(value) is not str or len(value) > maximum:
        raise ValueError('string')
    value.encode('utf8')
    return value


def pairs(items):
    out = {}
    for key, value in items:
        if key in out:
            raise ValueError('duplicate key')
        out[key] = value
    return out


def bad_constant(value):
    raise ValueError('nonfinite JSON')


def finite_float(value):
    result = float(value)
    if not math.isfinite(result):
        raise ValueError('nonfinite JSON number')
    return result


def visible_ascii(value):
    data = value.encode('ascii')
    if not data:
        raise ValueError('empty identity')
    if any(byte < 33 or byte > 126 for byte in data):
        raise ValueError('identity whitespace')
    return data


def compile_definitions(document):
    rows = sequence(document['definitions'], DEFINITIONS_LIMIT)
    definitions = []
    for row in rows:
        sequence(row, 2)
        if len(row) != 2:
            raise ValueError('definition pair')
        name = row[0]
        if not is_definition_name(name):
            raise ValueError('definition name')
        source = text(row[1], EXPRESSION_LIMIT)
        definitions.append((name, source))
    return definitions


def compile_cases_input(document):
    cases = sequence(document['cases'], CASES_LIMIT)
    names = set()
    budget = 0
    fields = 0
    prepared = []
    for case in cases:
        exact(case, ['name', 'frames', 'expect'])
        name = text(case['name'], 32)
        if not NAME.fullmatch(name) or name in names:
            raise ValueError('case name')
        names.add(name)
        frames = sequence(case['frames'], FRAMES_LIMIT)
        budget += len(frames)
        pauses = 0
        for frame in frames:
            kind = validate_frame(frame)
            if kind == 'sleep':
                pauses += frame['Time_to_Stop']
            elif kind == 'headers':
                if 'headers_kv' in frame:
                    fields += len(frame['headers_kv'])
                else:
                    fields += len(frame['data_to_transfered'])
        if pauses + document['timeout_ms'] > MAX:
            raise ValueError('virtual time budget')
        expect = case['expect']
        exact(expect, ['method', 'target', 'host'])
        identity = {}
        for key in ('method', 'target', 'host'):
            identity[key] = visible_ascii(text(expect[key], EXPECT_LIMIT))
        # Host identity compares after ASCII case folding on both sides.
        identity['host'] = identity['host'].lower()
        if TOKEN.fullmatch(identity['method']) is None:
            raise ValueError('expected method')
        prepared.append({'name': name, 'frames': frames, 'expect': identity})
    return prepared, names, budget, fields


def validate_frame(frame):
    if type(frame) is not dict:
        raise ValueError('frame')
    kind = frame.get('Type')
    if type(kind) is not str:
        raise ValueError('frame type')
    if kind == 'headers':
        mapping = 'headers_kv' in frame
        listed = 'data_to_transfered' in frame
        if mapping == listed:
            raise ValueError('header source')
        keys = {'Type', 'headers_kv' if mapping else 'data_to_transfered'}
        if 'End_Stream' in frame:
            if type(frame['End_Stream']) is not bool:
                raise ValueError('End_Stream')
            keys.add('End_Stream')
        if set(frame) != keys:
            raise ValueError('frame keys')
        if mapping:
            source = frame['headers_kv']
